#include <vector>
#include <algorithm>

class Solution {
public:
    int minOperationsI(std::vector<int>& nums, int k) {
        if (k < 2) return 0;
        std::vector<int> costEven(k, 0), costOdd(k, 0);
        for (int i = 0; i < (int)nums.size(); ++i) {
            int rem = nums[i] % k;
            for (int r = 0; r < k; ++r) {
                int c = std::min((rem - r + k) % k, (r - rem + k) % k);
                if (i % 2 == 0) costEven[r] += c;
                else costOdd[r] += c;
            }
        }
        int ans = 1e9;
        for (int x = 0; x < k; ++x) {
            for (int y = 0; y < k; ++y) {
                if (x != y) ans = std::min(ans, costEven[x] + costOdd[y]);
            }
        }
        return ans;
    }
};

class Solution {
    public int minOperationsI(int[] nums, int k) {
        if (k < 2) return 0;
        int[] costEven = new int[k];
        int[] costOdd = new int[k];
        for (int i = 0; i < nums.length; i++) {
            int rem = nums[i] % k;
            for (int r = 0; r < k; r++) {
                int c = Math.min((rem - r + k) % k, (r - rem + k) % k);
                if (i % 2 == 0) costEven[r] += c;
                else costOdd[r] += c;
            }
        }
        int ans = Integer.MAX_VALUE;
        for (int x = 0; x < k; x++) {
            for (int y = 0; y < k; y++) {
                if (x != y) ans = Math.min(ans, costEven[x] + costOdd[y]);
            }
        }
        return ans;
    }
}

